wall('trophy-fish','Чучело огромной рыбы',['таверна','порт'],2,(c,S,rnd,p,W)=>{wood(c,S,S*.2,0,W-S*.4,S*.12,P.dwood,rnd,'h',1);ell(c,W/2,S*.3,S*.7,S*.16);c.fillStyle=lg(c,0,S*.15,0,S*.45,['#8aa0a8','#3a5a64']);c.fill();ink(c,S,.02);c.stroke();poly(c,[[W/2+S*.65,S*.3],[W/2+S*.9,S*.12],[W/2+S*.9,S*.48]]);c.fill();c.stroke();c.fillStyle='#000';circ(c,W/2-S*.5,S*.27,S*.03);c.fill()});
wall('painting-portrait','Портрет предка',['замок','особняк'],1,(c,S)=>{c.fillStyle='#9a7328';c.fillRect(S*.2,0,S*.6,S*.14);c.fillStyle='#3a2a1a';c.fillRect(S*.25,S*.02,S*.5,S*.1);c.fillStyle='#c8a080';circ(c,S/2,S*.06,S*.03);c.fill()});
