const cel=(id,n,w,h,solid,f,cat,layer)=>add('cel-'+id,n,cat||'Культ',['небесное','храм','обитель ангелов'],w,h,solid,layer||'object',f);
cel('cloud','Облачный покров',2,2,false,(c,S,rnd,p,W)=>{for(let i=0;i<9;i++){circ(c,W*(.25+rnd()*.5),W*(.25+rnd()*.5),S*(.3+rnd()*.25));c.fillStyle=`rgba(255,255,255,${.35+rnd()*.3})`;c.fill()}},'Природа','floor');
cel('light-pillar','Столп света',1,1,false,(c,S)=>{glow(c,S/2,S/2,S*.9,'rgba(255,250,210,.6)');circ(c,S/2,S/2,S*.28);c.fillStyle=rg(c,S/2,S/2,0,S*.28,['#ffffff','rgba(255,240,180,.4)']);c.fill()},'Магия');
cel('feathers','Россыпь белых перьев',1,1,false,(c,S,rnd)=>{for(let i=0;i<8;i++){c.save();c.translate(S*(.15+rnd()*.7),S*(.15+rnd()*.7));c.rotate(rnd()*PI*2);c.beginPath();c.moveTo(0,-S*.09);c.quadraticCurveTo(S*.04,0,0,S*.09);c.quadraticCurveTo(-S*.04,0,0,-S*.09);c.fillStyle='#f8f6f0';c.fill();c.strokeStyle='rgba(150,150,160,.6)';c.lineWidth=S*.006;c.stroke();c.beginPath();c.moveTo(0,-S*.09);c.lineTo(0,S*.11);c.stroke();c.restore()}},'Декор','floor');
cel('mosaic','Звёздная мозаика пола',3,3,false,(c,S,rnd,p,W)=>{c.save();circ(c,W/2,W/2,W*.48);c.clip();for(let i=0;i<16;i++){c.beginPath();c.moveTo(W/2,W/2);c.arc(W/2,W/2,W*.48,i/16*PI*2,(i+1)/16*PI*2);c.closePath();c.fillStyle=i%2?'#f4f0e6':'#d8c890';c.fill()}c.restore();c.strokeStyle='#c49a3c';c.lineWidth=S*.04;circ(c,W/2,W/2,W*.48);c.stroke();c.beginPath();for(let i=0;i<16;i++){const a=i/16*PI*2,r=i%2?W*.15:W*.4;c.lineTo(W/2+Math.cos(a)*r,W/2+Math.sin(a)*r)}c.closePath();c.fillStyle='#d8b440';c.fill();c.stroke();circ(c,W/2,W/2,S*.2);c.fillStyle='#4a6fa8';c.fill();c.stroke()},'Декор','floor');
cel('chimes','Кристальные колокольчики',1,1,false,(c,S,rnd)=>{for(let i=0;i<7;i++){const a=i/7*PI*2;const x=S/2+Math.cos(a)*S*.25,y=S/2+Math.sin(a)*S*.25;poly(c,[[x,y-S*.06],[x+S*.03,y],[x,y+S*.06],[x-S*.03,y]]);c.fillStyle='rgba(220,240,255,.9)';c.fill();c.strokeStyle='#c49a3c';c.lineWidth=S*.008;c.stroke();c.beginPath();c.moveTo(S/2,S/2);c.lineTo(x,y);c.stroke()}glow(c,S/2,S/2,S*.5,'rgba(220,240,255,.4)')},'Декор','top');
cel('halo-fountain','Источник с нимбом',2,2,true,(c,S,rnd,p,W)=>{circ(c,W/2,W/2,S*.9);c.fillStyle=lg(c,0,0,W,W,['#f4f0e6','#bdb8ae']);c.fill();ink(c,S);c.stroke();circ(c,W/2,W/2,S*.7);c.fillStyle=rg(c,W/2,W/2,0,S*.7,['#ffffff','#a0d0f0']);c.fill();c.strokeStyle='#f2da7a';c.lineWidth=S*.06;circ(c,W/2,W/2,S*.35);c.stroke();glow(c,W/2,W/2,S*1.2,'rgba(255,240,180,.4)')},'Вода и лава');
cel('golden-gate','Золотые врата',3,1,true,(c,S,rnd,p,W)=>{stoneBlock(c,S,0,S*.3,S*.3,S*.4,P.marble,rnd);stoneBlock(c,S,W-S*.3,S*.3,S*.3,S*.4,P.marble,rnd);c.strokeStyle='#d8b440';c.lineWidth=S*.05;for(let x=S*.45;x<W-S*.3;x+=S*.2){c.beginPath();c.moveTo(x,S*.4);c.lineTo(x,S*.6);c.stroke()}c.beginPath();c.moveTo(S*.3,S*.5);c.lineTo(W-S*.3,S*.5);c.stroke();circ(c,W/2,S*.5,S*.15);c.fillStyle='#f2da7a';c.fill();ink(c,S,.02);c.stroke();glow(c,W/2,S/2,S,'rgba(255,230,150,.3)')},'Двери и окна');
