const elf=(id,n,th,w,h,solid,f,cat,layer)=>add('elf-'+id,n,cat||'Декор',th,w,h,solid,layer||'object',f);
elf('moonwell','Лунный колодец',['эльфы','фейвайлд'],2,2,true,(c,S,rnd,p,W)=>{for(let i=0;i<14;i++){const a=i/14*PI*2;c.save();c.translate(W/2+Math.cos(a)*S*.78,W/2+Math.sin(a)*S*.78);c.rotate(a);stoneBlock(c,S,-S*.1,-S*.14,S*.2,S*.28,P.marble,rnd);c.restore()}circ(c,W/2,W/2,S*.65);c.fillStyle=rg(c,W/2,W/2,0,S*.65,['#ffffff','#a0c8f0','#1a2a5a']);c.fill();ink(c,S);c.stroke();c.fillStyle='#ffffff';circ(c,W/2+S*.15,W/2-S*.1,S*.15);c.fill();c.fillStyle='#a0c8f0';circ(c,W/2+S*.2,W/2-S*.14,S*.13);c.fill();glow(c,W/2,W/2,S*1.2,'rgba(200,220,255,.4)')},'Вода и лава');
elf('platform','Помост на дереве',['эльфы','лес'],3,3,false,(c,S,rnd,p,W)=>{circ(c,W/2,W/2,W*.47);c.save();circ(c,W/2,W/2,W*.46);c.clip();for(let i=0;i<14;i++)wood(c,S,0,i*W/14,W,W/14,P.lwood,rnd,'h',1);c.restore();ink(c,S);circ(c,W/2,W/2,W*.46);c.stroke();circ(c,W/2,W/2,S*.4);c.fillStyle=rg(c,W/2,W/2,0,S*.4,['#9a6e44','#45301e']);c.fill();c.stroke();c.strokeStyle='#8a6a3a';c.lineWidth=S*.05;circ(c,W/2,W/2,W*.44);c.stroke()},'Мебель','floor');
elf('pavilion','Беседка из листвы',['эльфы','сад'],3,3,false,(c,S,rnd,p,W)=>{for(let i=0;i<6;i++){const a=i/6*PI*2;circ(c,W/2+Math.cos(a)*W*.4,W/2+Math.sin(a)*W*.4,S*.12);c.fillStyle='#e8e0d0';c.fill();ink(c,S,.02);c.stroke()}c.save();c.globalAlpha=.85;for(let i=0;i<30;i++){const a=rnd()*PI*2,d=rnd()*W*.45;ell(c,W/2+Math.cos(a)*d,W/2+Math.sin(a)*d,S*.25,S*.12,a);c.fillStyle=['#5a8a3a','#7aaa4a','#9ac060'][i%3];c.fill()}c.restore();for(let i=0;i<8;i++){circ(c,W*(.2+rnd()*.6),W*(.2+rnd()*.6),S*.05);c.fillStyle='#f0e0ff';c.fill()}},'Природа','top');
elf('lantern-tree','Дерево-светильник',['эльфы','фейвайлд'],2,2,true,(c,S,rnd,p,W)=>{M.render(c,'md2-tree-эльфийский-ясень-2',S,{seed:'lt'});for(let i=0;i<9;i++){const x=W*(.2+rnd()*.6),y=W*(.2+rnd()*.6);glow(c,x,y,S*.3,'rgba(255,240,170,.6)');circ(c,x,y,S*.05);c.fillStyle='#fff8d0';c.fill()}},'Свет','top');
elf('root-bench','Скамья из корней',['эльфы','лес','фейвайлд'],2,1,false,(c,S,rnd,p,W)=>{c.strokeStyle='#5a3c22';for(let i=0;i<6;i++){c.lineWidth=S*(.06+rnd()*.04);c.beginPath();c.moveTo(0,S*(.3+rnd()*.4));c.bezierCurveTo(W*.3,S*(.2+rnd()*.6),W*.7,S*(.2+rnd()*.6),W,S*(.3+rnd()*.4));c.stroke()}c.fillStyle='rgba(90,128,50,.8)';for(let i=0;i<5;i++){blob(c,rnd()*W,S*(.3+rnd()*.4),S*.08,rnd,6,.5);c.fill()}},'Мебель');
elf('flower-arch','Цветочная арка',['эльфы','сад','фейвайлд'],3,1,false,(c,S,rnd,p,W)=>{c.strokeStyle='#3a6a20';c.lineWidth=S*.08;c.beginPath();c.moveTo(S*.15,S*.5);c.quadraticCurveTo(W/2,S*.2,W-S*.15,S*.5);c.stroke();for(let i=0;i<14;i++){const t=i/13,x=S*.15+t*(W-S*.3),y=S*.5-Math.sin(t*PI)*S*.15;circ(c,x+(rnd()-.5)*S*.1,y+(rnd()-.5)*S*.1,S*.06);c.fillStyle=['#f0a0d0','#f4f0e6','#c080f0'][i%3];c.fill()}},'Природа','top');
elf('toadstool-table','Стол-поганка с табуретами-грибами',['фейвайлд'],2,2,true,(c,S,rnd,p,W)=>{const shr=(x,y,r)=>{shadow(c,S,()=>{circ(c,x,y,r);c.fillStyle='#000';c.fill()},.2);circ(c,x,y,r);c.fillStyle=rg(c,x-r*.3,y-r*.3,0,r,['#ff7a6a','#a01e18']);c.fill();ink(c,S,.02);c.stroke();c.fillStyle='#f4f0e6';for(let i=0;i<5;i++){circ(c,x+Math.cos(i*1.3)*r*.55,y+Math.sin(i*1.3)*r*.55,r*.13);c.fill()}};shr(W/2,W/2,S*.55);[[.25,.25],[1.75,.3],[.3,1.75],[1.7,1.7]].forEach(q=>shr(S*q[0],S*q[1],S*.2));T.mug(c,S,W/2-S*.15,W/2);T.mug(c,S,W/2+S*.15,W/2+S*.1)},'Мебель');
elf('dewdrop-pool','Пруд-росинка',['фейвайлд'],1,1,false,(c,S)=>{circ(c,S/2,S/2,S*.35);c.fillStyle=rg(c,S*.4,S*.4,0,S*.4,['#ffffff','#b0e8ff','#4a8ad8']);c.fill();c.strokeStyle='rgba(255,255,255,.8)';c.lineWidth=S*.02;c.stroke();circ(c,S*.4,S*.38,S*.08);c.fillStyle='rgba(255,255,255,.9)';c.fill()},'Вода и лава','floor');
elf('acorn-house','Дом-жёлудь',['фейвайлд','лес'],2,2,true,(c,S,rnd,p,W)=>{circ(c,W/2,W/2,S*.85);c.fillStyle=rg(c,W*.42,W*.42,0,S*.9,['#c8944a','#8a5a2a','#4a2a10']);c.fill();ink(c,S);c.stroke();c.save();circ(c,W/2,W/2,S*.55);c.clip();c.fillStyle='#5a3c22';c.fillRect(0,0,W,W);c.strokeStyle='#3a2414';c.lineWidth=S*.02;for(let i=-10;i<10;i++){c.beginPath();c.moveTo(W/2+i*S*.1,0);c.lineTo(W/2+i*S*.1+W,W);c.moveTo(W/2+i*S*.1,0);c.lineTo(W/2+i*S*.1-W,W);c.stroke()}c.restore();circ(c,W/2,W/2,S*.08);c.fillStyle='#3a2414';c.fill()},'Мебель');
elf('butterflies','Светящиеся бабочки',['фейвайлд','сад'],1,1,false,(c,S,rnd)=>{for(let i=0;i<5;i++){const x=S*(.2+rnd()*.6),y=S*(.2+rnd()*.6),col=['#ff9ae8','#9ae8ff','#fff09a'][i%3];glow(c,x,y,S*.12,'rgba(255,255,220,.5)');c.fillStyle=col;ell(c,x-S*.03,y,S*.03,S*.045,-.4);c.fill();ell(c,x+S*.03,y,S*.03,S*.045,.4);c.fill()}},'Природа','top');
elf('tea-set','Зачарованный чайный сервиз',['фейвайлд','особняк'],1,1,false,(c,S,rnd)=>{circ(c,S/2,S/2,S*.4);c.fillStyle='#e8e0d0';c.fill();ink(c,S,.015);c.stroke();circ(c,S/2,S/2,S*.12);c.fillStyle='#f4f0e6';c.fill();c.stroke();for(let i=0;i<4;i++){const a=i/4*PI*2+.4;circ(c,S/2+Math.cos(a)*S*.26,S/2+Math.sin(a)*S*.26,S*.06);c.fillStyle='#f8f0ff';c.fill();c.stroke();circ(c,S/2+Math.cos(a)*S*.26,S/2+Math.sin(a)*S*.26,S*.04);c.fillStyle='#a8643a';c.fill()}glow(c,S/2,S/2,S*.5,'rgba(255,180,240,.25)')},'Еда');
