const des=(id,n,w,h,solid,f,cat,layer)=>add('desert-'+id,n,cat||'Природа',['пустыня','оазис','караван'],w,h,solid,layer||'object',f);
des('dune','Бархан',3,2,false,(c,S,rnd,p,W,H)=>{c.beginPath();c.moveTo(0,H*.8);c.quadraticCurveTo(W*.3,H*.1,W*.6,H*.3);c.quadraticCurveTo(W*.85,H*.45,W,H*.85);c.closePath();c.fillStyle=lg(c,0,0,0,H,['#e8d4a0','#b8985a']);c.fill();c.beginPath();c.moveTo(W*.1,H*.75);c.quadraticCurveTo(W*.35,H*.2,W*.6,H*.3);c.strokeStyle='rgba(120,90,40,.6)';c.lineWidth=S*.03;c.stroke();c.strokeStyle='rgba(150,120,70,.35)';c.lineWidth=S*.012;for(let i=0;i<6;i++){c.beginPath();c.moveTo(W*(.4+i*.08),H*(.4+i*.05));c.quadraticCurveTo(W*(.5+i*.08),H*(.45+i*.06),W*(.6+i*.06),H*(.55+i*.05));c.stroke()}},'Природа','floor');
des('ruin-wall','Песчаниковая руина стены',3,1,true,(c,S,rnd,p,W)=>{for(let i=0;i<8;i++){const h=S*(.3+rnd()*.4);stoneBlock(c,S,S*i*.37,S*.5-h/2,S*.36,h,P.sand,rnd)}c.fillStyle='rgba(220,200,150,.6)';blob(c,W*.7,S*.8,S*.3,rnd,8,.4);c.fill()},'Обломки');
des('saddle','Верблюжье седло и поклажа',1,1,false,(c,S,rnd)=>{rr(c,S*.2,S*.25,S*.6,S*.5,S*.15);c.fillStyle='#952b22';c.fill();ink(c,S,.02);c.stroke();c.strokeStyle='#d8b440';c.lineWidth=S*.02;c.strokeRect(S*.28,S*.33,S*.44,S*.34);M.render(c,'md1-sack',S*.5,{seed:'sd'})},'Ёмкости');
des('tent','Бедуинский шатёр',3,2,true,(c,S,rnd,p,W,H)=>{shadow(c,S,()=>{c.fillStyle='#2a1a10';c.fillRect(S*.1,S*.1,W-S*.2,H-S*.2)});for(let i=0;i<8;i++){c.fillStyle=i%2?'#3a2a1a':'#6e1e18';c.fillRect(S*.1+i*(W-S*.2)/8,S*.1,(W-S*.2)/8,H-S*.2)}c.strokeStyle='#d8b440';c.lineWidth=S*.02;c.strokeRect(S*.1,S*.1,W-S*.2,H-S*.2);[.4,1.5,2.6].forEach(x=>{circ(c,S*x,H/2,S*.07);c.fillStyle='#5c4129';c.fill()})},'Мебель','top');
des('carpets','Стопка ковров торговца',2,1,true,(c,S,rnd,p,W)=>{['#952b22','#1f3560','#406236','#9a7328'].forEach((k,i)=>{c.save();c.translate(W/2+(i-1.5)*S*.05,S/2-(i-1.5)*S*.04);c.rotate((rnd()-.5)*.1);c.fillStyle=k;c.fillRect(-S*.85,-S*.35,S*1.7,S*.7);c.strokeStyle='#e8d090';c.lineWidth=S*.025;c.strokeRect(-S*.78,-S*.28,S*1.56,S*.56);c.restore()})},'Ковры');
des('hookah','Кальян на подушках',1,1,true,(c,S)=>{[[.2,.2,'#952b22'],[.8,.2,'#1f3560'],[.2,.8,'#406236'],[.8,.8,'#5a3470']].forEach(q=>{rr(c,S*q[0]-S*.15,S*q[1]-S*.15,S*.3,S*.3,S*.1);c.fillStyle=q[2];c.fill();ink(c,S,.015);c.stroke()});circ(c,S/2,S/2,S*.14);c.fillStyle=lg(c,0,0,S,S,['#e2c068','#6e4f1c']);c.fill();ink(c,S,.015);c.stroke();c.strokeStyle='#6e1e18';c.lineWidth=S*.02;c.beginPath();c.moveTo(S/2,S/2);c.quadraticCurveTo(S*.7,S*.4,S*.75,S*.75);c.stroke();circ(c,S/2,S/2,S*.05);c.fillStyle='#d8520e';c.fill()},'Декор');
des('dates','Корзины фиников и смокв',1,1,false,(c,S,rnd)=>{[[.32,.35],[.68,.62]].forEach((q,i)=>{circ(c,S*q[0],S*q[1],S*.22);c.fillStyle='#a8844a';c.fill();ink(c,S,.015);c.stroke();for(let k=0;k<10;k++){ell(c,S*q[0]+(rnd()-.5)*S*.25,S*q[1]+(rnd()-.5)*S*.25,S*.035,S*.02,rnd()*3);c.fillStyle=i?'#5a2a4a':'#6e3a14';c.fill()}})},'Еда');
des('sandstone-statue-head','Голова колосса в песке',2,2,true,(c,S,rnd,p,W)=>{c.fillStyle='rgba(220,200,150,.7)';blob(c,W/2,W/2,W*.48,rnd,12,.2);c.fill();ell(c,W/2,W/2,S*.65,S*.8);c.fillStyle=lg(c,0,0,W,0,['#a08654','#dcc898','#a08654']);c.fill();ink(c,S);c.stroke();c.fillStyle='#7a6440';ell(c,W/2-S*.25,W/2-S*.15,S*.12,S*.06);c.fill();ell(c,W/2+S*.25,W/2-S*.15,S*.12,S*.06);c.fill();c.fillRect(W/2-S*.05,W/2-S*.1,S*.1,S*.3);c.fillRect(W/2-S*.2,W/2+S*.35,S*.4,S*.06);M.cracks(c,S,W*.3,W*.2,W*.4,W*.6,rnd,3)},'Статуи');
