const snow=(id,n,w,h,solid,f,cat,layer)=>add('snow-'+id,n,cat||'Природа',['снег','север','ледник'],w,h,solid,layer||'object',f);
snow('ice-wall','Стена из ледяных блоков',3,1,true,(c,S,rnd,p,W)=>{for(let i=0;i<6;i++)for(let j=0;j<2;j++){rr(c,S*(i*.5+(j%2)*.25)-S*.1,S*(.15+j*.35),S*.48,S*.33,S*.04);c.fillStyle=lg(c,0,0,S,S,['#e8f8ff','#8ab8d0']);c.fill();c.strokeStyle='rgba(60,100,130,.6)';c.lineWidth=S*.015;c.stroke()}},'Обломки');
snow('igloo','Иглу',3,3,true,(c,S,rnd,p,W)=>{circ(c,W/2,W/2,W*.42);c.fillStyle=rg(c,W*.42,W*.42,0,W*.45,['#ffffff','#c8dce8','#8aa8c0']);c.fill();ink(c,S);c.stroke();c.strokeStyle='rgba(100,130,160,.5)';c.lineWidth=S*.015;for(let r=.12;r<.42;r+=.08){circ(c,W/2,W/2,W*r);c.stroke()}for(let i=0;i<16;i++){const a=i/16*PI*2;c.beginPath();c.moveTo(W/2+Math.cos(a)*W*.12,W/2+Math.sin(a)*W*.12);c.lineTo(W/2+Math.cos(a)*W*.42,W/2+Math.sin(a)*W*.42);c.stroke()}rr(c,W/2-S*.3,W*.85,S*.6,S*.45,S*.15);c.fillStyle='#d8e8f0';c.fill();ink(c,S,.02);c.stroke();c.fillStyle='#1a2a3a';rr(c,W/2-S*.18,W*.9,S*.36,S*.35,S*.1);c.fill()},'Мебель');
snow('sled','Сани с поклажей',1,2,true,(c,S,rnd,p,W,H)=>{c.strokeStyle='#5c4129';c.lineWidth=S*.04;[S*.2,S*.8].forEach(x=>{c.beginPath();c.moveTo(x,H-S*.1);c.lineTo(x,S*.3);c.quadraticCurveTo(x,S*.05,S/2,S*.05);c.stroke()});wood(c,S,S*.2,S*.4,S*.6,S*1.4,P.lwood,rnd,'h',5);M.render&&0;c.save();c.translate(S*.3,S*.6);M.render(c,'md1-crate-small',S*.8,{seed:'sl'});c.restore();c.save();c.translate(S*.1,S*1.1);M.render(c,'md1-sack',S*.8,{seed:'sl2'});c.restore()},'Механизмы');
snow('snowman','Снеговик',1,1,true,(c,S)=>{[[.5,.6,.3],[.5,.42,.2]].forEach(q=>{circ(c,S*q[0],S*q[1],S*q[2]);c.fillStyle=rg(c,S*q[0]-S*.05,S*q[1]-S*.05,0,S*q[2],['#ffffff','#c8dce8']);c.fill();ink(c,S,.02);c.stroke()});c.fillStyle='#e8782a';poly(c,[[S*.5,S*.4],[S*.5,S*.48],[S*.62,S*.44]]);c.fill();c.fillStyle='#22170e';circ(c,S*.45,S*.38,S*.02);c.fill();circ(c,S*.55,S*.38,S*.02);c.fill()},'Декор');
snow('ice-throne','Ледяной трон',2,2,true,(c,S,rnd,p,W)=>{const CR=['#7ab8d8','#2a5a7a','#f0ffff'];for(let i=0;i<9;i++){const a=PI+i/8*PI;c.save();c.translate(W/2,W*.6);c.rotate(a);poly(c,[[0,-S*.08],[S*.95,0],[0,S*.08]]);c.fillStyle=lg(c,0,0,S,0,[CR[2],CR[0]]);c.fill();ink(c,S,.012);c.stroke();c.restore()}rr(c,W/2-S*.45,W*.45,S*.9,S*.8,S*.1);c.fillStyle=lg(c,0,0,W,W,['#e8f8ff','#7ab8d8']);c.fill();ink(c,S);c.stroke();glow(c,W/2,W/2,S*1.2,'rgba(200,240,255,.3)')},'Мебель');
snow('fur-pile','Груда шкур',1,1,false,(c,S,rnd)=>{for(let i=0;i<4;i++){c.save();c.translate(S/2,S/2);c.rotate(rnd()*PI);blob(c,0,0,S*.35,rnd,9,.4);c.fillStyle=['#6a5236','#a8a8a0','#3a2a1a','#d8d8d0'][i];c.fill();ink(c,S,.015);c.stroke();c.restore()}},'Ковры');
snow('frozen-pond','Замёрзший пруд',3,3,false,(c,S,rnd,p,W)=>{blob(c,W/2,W/2,W*.44,rnd,12,.25);c.fillStyle=rg(c,W*.4,W*.4,0,W*.5,['#e8f8ff','#a0c8dc','#6a98b0']);c.fill();ink(c,S,.02);c.stroke();c.strokeStyle='rgba(255,255,255,.8)';c.lineWidth=S*.015;for(let i=0;i<6;i++){let x=W*(.3+rnd()*.4),y=W*(.3+rnd()*.4);c.beginPath();c.moveTo(x,y);for(let k=0;k<4;k++){x+=(rnd()-.5)*S*.6;y+=(rnd()-.5)*S*.6;c.lineTo(x,y)}c.stroke()}c.fillStyle='#1a3a4a';blob(c,W*.65,W*.6,S*.2,rnd,8,.4);c.fill()},'Вода и лава','floor');
snow('ski-rack','Лыжи и снегоступы',1,1,false,(c,S)=>{for(let i=0;i<3;i++){rr(c,S*(.18+i*.12),S*.08,S*.07,S*.84,S*.03);c.fillStyle='#8a6239';c.fill();ink(c,S,.012);c.stroke()}ell(c,S*.75,S*.5,S*.14,S*.25);c.strokeStyle='#5c4129';c.lineWidth=S*.025;c.stroke();for(let i=0;i<4;i++){c.beginPath();c.moveTo(S*.62,S*(.35+i*.1));c.lineTo(S*.88,S*(.35+i*.1));c.lineWidth=S*.008;c.stroke()}},'Декор');
