const floor=(id,n,th,f)=>add('floor-'+id,n,'Декор',th,2,2,false,'floor',(c,S,rnd,p,W)=>{c.save();c.beginPath();c.rect(0,0,W,W);c.clip();f(c,S,rnd,W);c.restore()});
floor('planks','Пол: дощатый',['таверна','дом','корабль'],(c,S,rnd,W)=>{for(let i=0;i<8;i++){const off=(i%2)*S*.7;wood(c,S,-off,i*W/8,S*1.4,W/8,P.wood,rnd,'h',1);wood(c,S,S*1.4-off,i*W/8,S*1.4,W/8,P.wood,rnd,'h',1)}});
floor('flagstone','Пол: каменные плиты',['замок','подземелье','храм'],(c,S,rnd,W)=>{for(let i=0;i<4;i++)for(let j=0;j<4;j++)stoneBlock(c,S,i*S*.5+S*.01,j*S*.5+S*.01,S*.48,S*.48,rnd()<.3?P.dstone:P.stone,rnd)});
floor('cobble','Мостовая: булыжник',['город','улица'],(c,S,rnd,W)=>{c.fillStyle='#3a3530';c.fillRect(0,0,W,W);for(let i=0;i<7;i++)for(let j=0;j<7;j++){blob(c,S*(.15+i*.29+(j%2)*.14),S*(.15+j*.29),S*.13,rnd,7,.3);c.fillStyle=rg(c,S*(.12+i*.29),S*(.12+j*.29),0,S*.15,['#a8a399','#6a6761']);c.fill();ink(c,S,.012);c.stroke()}});
floor('marble-check','Пол: мраморная шахматка',['дворец','храм','особняк'],(c,S,rnd,W)=>{for(let i=0;i<4;i++)for(let j=0;j<4;j++){c.fillStyle=(i+j)%2?'#2a2a30':'#e8e3d8';c.fillRect(i*S*.5,j*S*.5,S*.5,S*.5);c.strokeStyle=(i+j)%2?'rgba(120,120,140,.3)':'rgba(150,140,120,.35)';c.lineWidth=S*.008;c.beginPath();c.moveTo(i*S*.5+rnd()*S*.5,j*S*.5);c.quadraticCurveTo(i*S*.5+rnd()*S*.5,j*S*.5+S*.25,i*S*.5+rnd()*S*.5,j*S*.5+S*.5);c.stroke()}c.strokeStyle='rgba(0,0,0,.3)';c.lineWidth=S*.01;for(let i=0;i<=4;i++){c.beginPath();c.moveTo(i*S*.5,0);c.lineTo(i*S*.5,W);c.moveTo(0,i*S*.5);c.lineTo(W,i*S*.5);c.stroke()}});
floor('mosaic','Пол: мозаика',['храм','термы','дворец'],(c,S,rnd,W)=>{const k=S*.1;for(let x=0;x<W;x+=k)for(let y=0;y<W;y+=k){const d=Math.hypot(x-W/2,y-W/2)/S;c.fillStyle=['#e8e0c8','#2f4f86','#b8463a','#d8b440','#e8e0c8'][Math.floor(d*3)%5];c.fillRect(x+S*.005,y+S*.005,k-S*.01,k-S*.01)}});
floor('dirt','Пол: утоптанная земля',['хижина','лагерь','шахта'],(c,S,rnd,W)=>{c.fillStyle='#6a5236';c.fillRect(0,0,W,W);for(let i=0;i<120;i++){circ(c,rnd()*W,rnd()*W,S*(.01+rnd()*.03));c.fillStyle=rnd()<.5?'rgba(40,28,15,.4)':'rgba(140,110,70,.4)';c.fill()}});
floor('herringbone','Пол: паркет ёлочкой',['особняк','дворец'],(c,S,rnd,W)=>{c.fillStyle=P.wood[1];c.fillRect(0,0,W,W);const L=S*.35,w=S*.12;for(let x=-L;x<W+L;x+=w*2)for(let y=-L;y<W+L;y+=L){[[x,y,PI/4],[x+w,y,-PI/4]].forEach(q=>{c.save();c.translate(q[0],q[1]);c.rotate(q[2]);c.fillStyle=P.wood[1+((Math.abs(x+y)/w|0)%3)];c.fillRect(0,0,L,w);c.strokeStyle='rgba(20,12,6,.5)';c.lineWidth=S*.008;c.strokeRect(0,0,L,w);c.restore()})}});
floor('grate','Пол: металлическая решётка',['канализация','тюрьма','мастерская'],(c,S,rnd,W)=>{c.fillStyle='#0a0806';c.fillRect(0,0,W,W);c.strokeStyle='#45484d';c.lineWidth=S*.04;for(let i=0;i<=10;i++){c.beginPath();c.moveTo(i*W/10,0);c.lineTo(i*W/10,W);c.moveTo(0,i*W/10);c.lineTo(W,i*W/10);c.stroke()}});
floor('straw','Пол: солома',['конюшня','амбар','тюрьма'],(c,S,rnd,W)=>{c.fillStyle='#8a7040';c.fillRect(0,0,W,W);c.lineWidth=S*.012;for(let i=0;i<300;i++){const x=rnd()*W,y=rnd()*W,a=rnd()*PI;c.strokeStyle=['#d8c070','#b0943a','#e8d890'][i%3];c.beginPath();c.moveTo(x,y);c.lineTo(x+Math.cos(a)*S*.15,y+Math.sin(a)*S*.15);c.stroke()}});
floor('cave','Пол: неровный камень пещеры',['пещера','подземье'],(c,S,rnd,W)=>{c.fillStyle='#4a4540';c.fillRect(0,0,W,W);for(let i=0;i<14;i++){blob(c,rnd()*W,rnd()*W,S*(.2+rnd()*.3),rnd,8,.5);c.fillStyle=`rgba(${rnd()<.5?'0,0,0':'160,150,140'},.15)`;c.fill()}M.cracks(c,S,0,0,W,W,rnd,5)});
