wseg('stone-corner','Угол каменной стены',['подземелье','замок'],2,2,(c,S,rnd,p,W)=>{for(let i=0;i<4;i++)for(let j=0;j<2;j++)stoneBlock(c,S,S*i*.5,S*(.25+j*.25),S*.5,S*.25,P.stone,rnd);for(let i=1;i<4;i++)for(let j=0;j<2;j++)stoneBlock(c,S,S*(.25+j*.25),S*(i*.5+.25),S*.25,S*.5,P.stone,rnd)});
