wseg('timber','Бревенчатая стена',['деревня','лес','север'],3,1,(c,S,rnd,p,W)=>{for(let j=0;j<2;j++){rr(c,0,S*(.3+j*.2),W,S*.2,S*.1);c.fillStyle=lg(c,0,S*(.3+j*.2),0,S*(.5+j*.2),['#9a6e44','#5a3c22']);c.fill();ink(c,S,.015);c.stroke()}});
