wseg('palisade-gate','Ворота частокола',['лагерь','деревня','крепость'],3,1,(c,S,rnd,p,W)=>{for(let x=S*.1;x<S*.7;x+=S*.2){circ(c,x,S/2,S*.11);c.fillStyle='#7a5432';c.fill();ink(c,S,.015);c.stroke()}for(let x=W-S*.1;x>W-S*.7;x-=S*.2){circ(c,x,S/2,S*.11);c.fillStyle='#7a5432';c.fill();ink(c,S,.015);c.stroke()}wood(c,S,S*.7,S*.4,W-S*1.4,S*.2,P.wood,rnd,'v',6)},'Двери и окна');
