const st=(id,n,th,w,h,f,solid)=>add('stairs-'+id,n,'Двери и окна',th,w,h,!!solid,'floor',f);
st('down','Лестница вниз',['подземелье','замок'],1,2,(c,S,rnd,p,W,H)=>{for(let i=0;i<8;i++){const t=i/8;c.fillStyle=`rgb(${150-t*130},${145-t*125},${135-t*120})`;c.fillRect(S*.05,i*H/8,S*.9,H/8);c.strokeStyle='rgba(0,0,0,.5)';c.lineWidth=S*.015;c.strokeRect(S*.05,i*H/8,S*.9,H/8)}ink(c,S);c.strokeRect(S*.05,0,S*.9,H);c.fillStyle='rgba(255,255,255,.7)';poly(c,[[S/2,H*.85],[S*.4,H*.7],[S*.6,H*.7]]);c.fill()});
st('up','Лестница вверх',['подземелье','замок','башня'],1,2,(c,S,rnd,p,W,H)=>{for(let i=0;i<8;i++){const t=1-i/8;c.fillStyle=`rgb(${200-t*80},${195-t*80},${185-t*80})`;c.fillRect(S*.05,i*H/8,S*.9,H/8);c.strokeStyle='rgba(0,0,0,.45)';c.lineWidth=S*.015;c.strokeRect(S*.05,i*H/8,S*.9,H/8)}ink(c,S);c.strokeRect(S*.05,0,S*.9,H);c.fillStyle='rgba(30,20,10,.7)';poly(c,[[S/2,H*.15],[S*.4,H*.3],[S*.6,H*.3]]);c.fill()});
st('wide','Широкая парадная лестница',['дворец','замок','храм'],3,2,(c,S,rnd,p,W,H)=>{for(let i=0;i<8;i++){stoneBlock(c,S,S*.02,i*H/8,W-S*.04,H/8,i%2?P.marble:P.stone,rnd)}c.fillStyle='#6e1e18';c.fillRect(W/2-S*.4,0,S*.8,H)});
